      "build": "以抗性、生命和团队功能装为主，根据敌方主要伤害类型调整物防或魔防。",
      "arcana": "优先生命、移速、冷却和抗性铭文，保证开视野、承伤和保护能力。",
      "summonerSpell": "闪现或净化，按敌方控制强度选择。",
