    "guideStatus": "complete",
    "guide": {
      "positioning": "伽罗 的主要定位是射手，推荐分路为发育路。核心思路是围绕自身强势期建立节奏，避免在技能真空期硬接团。",
      "recommendedLane": "发育路",
      "skillPoints": "先熟悉核心技能的控制、位移、强化普攻或保护机制，进场前确认关键技能是否可用；技能交完后要及时拉开，等待下一轮冷却。",
      "build": "先做攻速、暴击或穿透核心装，再补逐日之弓、泣血之刃、复活甲或名刀等保命装。",
      "arcana": "优先攻速、暴击、物穿和移速铭文，保证前期补刀和后期输出手感。",
      "summonerSpell": "闪现。",
      "combos": "常用思路是先用消耗或控制技能创造命中条件，再接主要输出技能；有位移的英雄要保留一段撤退，有控制的英雄要把控制交给关键目标。",
      "laning": "前期以稳定清线、补经济和观察小地图为主。取得线权后再支援河道、野区或边路，没视野时不要单独深入草丛和河道。",
      "teamFight": "团战先明确职责：输出位保持安全距离，刺客寻找后排机会，前排负责承伤和开团，辅助优先保护核心。不要为了追残血脱离队伍太远。",
      "counters": "更容易处理缺少位移、站位靠前、血量被压低或关键技能刚交过的目标。",
      "counteredBy": "怕连续控制、多人集火、视野压制和针对性装备。遇到强开阵容时要更重视站位和保命技能。",
      "tips": "玩伽罗时先保证经济和视野，再追求单杀。新手优先练清线、支援、撤退路线和团战站位。"
    },
