      "positioning": "镜 的主要定位是刺客，推荐分路为打野。核心思路是围绕自身强势期建立节奏，避免在技能真空期硬接团。",
      "recommendedLane": "打野",
      "skillPoints": "先熟悉核心技能的控制、位移、强化普攻或保护机制，进场前确认关键技能是否可用；技能交完后要及时拉开，等待下一轮冷却。",
      "build": "优先成型打野刀、穿透和爆发装，顺风补破军，逆风保留名刀或复活甲。",
      "arcana": "优先物理穿透、攻击、移速和少量续航铭文，提升对线或打野节奏。",
      "summonerSpell": "惩击。",
      "combos": "常用思路是先用消耗或控制技能创造命中条件，再接主要输出技能；有位移的英雄要保留一段撤退，有控制的英雄要把控制交给关键目标。",
      "laning": "前期以稳定清线、补经济和观察小地图为主。取得线权后再支援河道、野区或边路，没视野时不要单独深入草丛和河道。",
      "teamFight": "团战先明确职责：输出位保持安全距离，刺客寻找后排机会，前排负责承伤和开团，辅助优先保护核心。不要为了追残血脱离队伍太远。",
