      "positioning": "元流之子(法师) 的主要定位是法师，推荐分路为中路。核心思路是围绕自身强势期建立节奏，避免在技能真空期硬接团。",
      "recommendedLane": "中路",
      "skillPoints": "先熟悉核心技能的控制、位移、强化普攻或保护机制，进场前确认关键技能是否可用；技能交完后要及时拉开，等待下一轮冷却。",
      "build": "先做法术强度、冷却或法穿核心装，后期根据敌方魔抗补虚无法杖、辉月或保命装。",
      "arcana": "优先法术穿透、法术攻击、冷却和移速铭文，提升清线和支援效率。",
