      "positioning": "孙权 的主要定位是射手，推荐分路为发育路。核心思路是围绕自身强势期建立节奏，避免在技能真空期硬接团。",
      "recommendedLane": "发育路",
      "skillPoints": "先熟悉核心技能的控制、位移、强化普攻或保护机制，进场前确认关键技能是否可用；技能交完后要及时拉开，等待下一轮冷却。",
      "build": "先做攻速、暴击或穿透核心装，再补逐日之弓、泣血之刃、复活甲或名刀等保命装。",
      "arcana": "优先攻速、暴击、物穿和移速铭文，保证前期补刀和后期输出手感。",
